import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/vcpkg.html","title":"vcpkg","lang":"en-US","frontmatter":{},"git":{"createdTime":1750219568000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":3}]},"readingTime":{"minutes":1.13,"words":340},"filePathRelative":"vcpkg.md"}`),a={name:`vcpkg.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="vcpkg" tabindex="-1"><a class="header-anchor" href="#vcpkg"><span>vcpkg</span></a></h1><p>このWiki内の関連ページ: <a href="./VisualStudio.html">VisualStudio</a>、<a href="./VSCode.html">VSCode</a>, <a href="./vcpkgでQt5.html">vcpkgでQt5</a></p><ul><li><a href="https://learn.microsoft.com/ja-jp/vcpkg/reference/vcpkg-json" target="_blank" rel="noopener noreferrer">vcpkg.json リファレンス - Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/ja-jp/vcpkg/get_started/get-started?pivots=shell-powershell" target="_blank" rel="noopener noreferrer">CMake でパッケージをインストールして使用する - Microsoft Learn</a> 新しく作る時の雛形として手頃な記事。</li><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/examples/patching.md" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/examples/patching.md at main · MicrosoftDocs/vcpkg-docs</a> パッチを作る時のハウツー</li><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/contributing/maintainer-guide.md" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/contributing/maintainer-guide.md at main · MicrosoftDocs/vcpkg-docs</a> PRのガイド <ul><li><a href="https://github.com/microsoft/vcpkg/pull/48888" target="_blank" rel="noopener noreferrer">[ginkgo] Update to 1.11.0 by MarcelKoch · Pull Request #48888 · microsoft/vcpkg</a> 参考になりそうなマージされたPR</li></ul></li></ul><h2 id="baselineのアップデート" tabindex="-1"><a class="header-anchor" href="#baselineのアップデート"><span>baselineのアップデート</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% vcpkg x-update-baseline</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="cmakeから使うミニマムな例" tabindex="-1"><a class="header-anchor" href="#cmakeから使うミニマムな例"><span>CMakeから使うミニマムな例</span></a></h2><p>手順は以下に書いてある。</p><p><a href="https://learn.microsoft.com/en-us/vcpkg/users/buildsystems/cmake-integration" target="_blank" rel="noopener noreferrer">vcpkg in CMake projects - Microsoft Learn</a></p><p>CMAKE_TOOLCHAIN_FILEでvcpkgのものを指定する。そのための推奨の方法はCMakePresets.jsonを使う、との事だが、CMakeLists.txtの冒頭に以下の方がミニマムか。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">if(DEFINED ENV{VCPKG_ROOT} AND NOT DEFINED CMAKE_TOOLCHAIN_FILE)</span>
<span class="line">    set(CMAKE_TOOLCHAIN_FILE &quot;$ENV{VCPKG_ROOT}/scripts/buildsystems/vcpkg.cmake&quot;)</span>
<span class="line">endif()</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これは<code>project()</code>の前にセットしなくてはいけない。VCPKG_ROOTはまぁみんな定義しているだろう。</p><h2 id="マニフェストモードでのライブラリの共有" tabindex="-1"><a class="header-anchor" href="#マニフェストモードでのライブラリの共有"><span>マニフェストモードでのライブラリの共有</span></a></h2><p>Qtなどをvcpkgで入れる場合、流石にプロジェクトごとにビルドするのはイマイチだがVSのvcpkgではクラシックモードで動かすのもどうすべきか微妙だったりするのでどうしたもんか、と調べていたところ、バイナリキャッシュを特定のディレクトリに置いてそれを共有する仕組みがあるらしい。 こちらの方が王道っぽいな。</p><ul><li><a href="https://learn.microsoft.com/en-us/vcpkg/consume/binary-caching-local?pivots=shell-powershell" target="_blank" rel="noopener noreferrer">Tutorial: Set up a vcpkg binary cache using filesystem directories - Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/vcpkg/consume/binary-caching-default?pivots=shell-powershell" target="_blank" rel="noopener noreferrer">Default local vcpkg binary cache - Microsoft Learn</a></li></ul><p>デフォルトでAppData/Local/vcpkgの下が使われているっぽいな。なんかこれでいい気がするな。</p><h3 id="windowsでの作業ログ" tabindex="-1"><a class="header-anchor" href="#windowsでの作業ログ"><span>Windowsでの作業ログ</span></a></h3><p>手作業での指定を一応試してみる。</p><ol><li>ディレクトリを適当に作る</li></ol><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">mkdir ~/source/vcpkg_cache</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>環境変数を設定する</li></ol><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$env:VCPKG_BINARY_SOURCES=&quot;clear;filesystem,C:\\Users\\karino2\\source\\vcpkg_cache\\vcpkg_cache,read-write&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="vcpkgにprを出す" tabindex="-1"><a class="header-anchor" href="#vcpkgにprを出す"><span>vcpkgにPRを出す</span></a></h2><p>qt5-webengineの最新macとwindowsのビルド通す作業を行ったので、vcpkgの本家に入れられないかPRを出して相談してみる。</p><ul><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/produce/update-package-version.md" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/produce/update-package-version.md at main · MicrosoftDocs/vcpkg-docs</a></li><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/contributing/pr-review-checklist.md" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/contributing/pr-review-checklist.md at main · MicrosoftDocs/vcpkg-docs</a></li><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/concepts/registries.md#versions-files" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/concepts/registries.md at main · MicrosoftDocs/vcpkg-docs</a></li><li><a href="https://github.com/MicrosoftDocs/vcpkg-docs/blob/main/vcpkg/contributing/maintainer-guide.md" target="_blank" rel="noopener noreferrer">vcpkg-docs/vcpkg/contributing/maintainer-guide.md at main · MicrosoftDocs/vcpkg-docs</a> ここにdraft PRを使え、と書いてある。やってみよう。</li></ul><h3 id="prを作る-2025-12-19-金" tabindex="-1"><a class="header-anchor" href="#prを作る-2025-12-19-金"><span>PRを作る 2025-12-19 (金)</span></a></h3><p>とりあえずmasterを上げてrebaseして動作を確認したので、draft PRを作ってみた。</p><p><a href="https://github.com/microsoft/vcpkg/pull/48960" target="_blank" rel="noopener noreferrer">[qt5-webengine] Latest mac, win build support. (fix #47010) by karino2 · Pull Request #48960 · microsoft/vcpkg</a></p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};